# frozen_string_literal: true

require "rails_helper"

RSpec.describe Timekeeping::Alerts do
  it "raises reference_unavailable only for the company over 1 percent, never pooling a busy company's writes" do
    now = Time.utc(2026, 3, 3, 12, 10)
    completed_window = (now - 300).iso8601
    window = lambda do |writes, unavailable|
      { "window_start" => completed_window, "writes" => writes, "reference_unavailable" => unavailable,
        "stale_generation" => 0, "latency_ms_sum" => (writes + unavailable) * 10,
        "latency_ms_buckets" => { "25" => writes + unavailable } }
    end
    # Company 101 fails 2 of 100 requests (2%). Company 202 fails 50 of 10000 (0.5%).
    # Pooled, the two would be 52 of 10100 (about 0.51%) and raise nothing.
    metrics = {
      "latency_bucket_bounds_ms" => [25, 50, 100, 200, 300, 500, 1000, 2500, 5000],
      "overflow_bucket" => "inf",
      "total_field" => "writes + reference_unavailable",
      "companies" => [
        { "company_id" => 101, "windows" => [window.call(98, 2)] },
        { "company_id" => 202, "windows" => [window.call(9950, 50)] }
      ]
    }
    signals = Timekeeping::Alerts::Signals.new(
      now:, outbox_lag_seconds_by_company: {}, pending_intent_age_seconds_by_company: {}, write_pause_seconds: 0,
      stale_generation_outside_handoff_by_company: {}, write_metrics: metrics, prepare_refusals_by_company: nil,
      unexplained_reconciliation_differences_by_company: nil, financial_snapshot_changes_by_company: nil
    )

    # "It logs each alert with `company_id`."
    alerts = Timekeeping::Alerts.evaluate(signals).select { |alert| alert.name.to_s == "reference_unavailable" }

    expect(alerts.map(&:company_id)).to eq([101])
  end
end

RSpec.describe Timekeeping::Alerts do
  it "decides p95 entry write latency per company, so a fast busy company never hides a slow one" do
    now = Time.utc(2026, 3, 3, 12, 7)
    current_window = Time.utc(2026, 3, 3, 12, 5).iso8601
    # Company 303: 20 writes, all in the "500" bucket, so its p95 is over 300 ms.
    # Company 404: 10000 writes in the "100" bucket. Pooled, p95 would sit in "100".
    metrics = {
      "latency_bucket_bounds_ms" => [25, 50, 100, 200, 300, 500, 1000, 2500, 5000],
      "overflow_bucket" => "inf",
      "total_field" => "writes + reference_unavailable",
      "companies" => [
        { "company_id" => 303, "windows" => [{ "window_start" => current_window, "writes" => 20,
                                                "reference_unavailable" => 0, "stale_generation" => 0,
                                                "latency_ms_sum" => 20 * 400, "latency_ms_buckets" => { "500" => 20 } }] },
        { "company_id" => 404, "windows" => [{ "window_start" => current_window, "writes" => 10_000,
                                                "reference_unavailable" => 0, "stale_generation" => 0,
                                                "latency_ms_sum" => 10_000 * 80, "latency_ms_buckets" => { "100" => 10_000 } }] }
      ]
    }
    signals = Timekeeping::Alerts::Signals.new(
      now:, outbox_lag_seconds_by_company: {}, pending_intent_age_seconds_by_company: {}, write_pause_seconds: 0,
      stale_generation_outside_handoff_by_company: {}, write_metrics: metrics, prepare_refusals_by_company: nil,
      unexplained_reconciliation_differences_by_company: nil, financial_snapshot_changes_by_company: nil
    )

    alerts = Timekeeping::Alerts.evaluate(signals)

    expect(alerts.map(&:company_id)).to eq([303])
    expect(alerts.sole.log_line).to include("company_id=303")
    expect(alerts.sole.log_line).not_to include("404")
  end
end

RSpec.describe Timekeeping::Alerts do
