      outbox_lag_seconds_by_company: { 11 => 301, 22 => 299 },
      pending_intent_age_seconds_by_company: { 11 => 601, 22 => 599 },
      write_pause_seconds: 0,
      stale_generation_outside_handoff_by_company: { 11 => 1, 22 => 0 },
      write_metrics: metrics,
