RSpec.describe Timekeeping::Alerts, "window selection" do
  def alerts_window_signals(now:, windows:)
    Timekeeping::Alerts::Signals.new(
      now:, outbox_lag_seconds_by_company: {}, pending_intent_age_seconds_by_company: {}, write_pause_seconds: 0,
      stale_generation_outside_handoff_by_company: {},
      write_metrics: {
        "latency_bucket_bounds_ms" => [25, 50, 100, 200, 300, 500, 1000, 2500, 5000], "overflow_bucket" => "inf",
        "total_field" => "writes + reference_unavailable",
        "companies" => [{ "company_id" => 5, "windows" => windows }]
      },
      prepare_refusals_by_company: {}, unexplained_reconciliation_differences_by_company: {},
      financial_snapshot_changes_by_company: {}
    )
  end

  def alerts_window(start, writes:, unavailable: 0, buckets: nil)
    { "window_start" => start.iso8601, "writes" => writes, "reference_unavailable" => unavailable,
      "stale_generation" => 0, "latency_ms_sum" => 0, "latency_ms_buckets" => buckets || { "25" => writes + unavailable } }
  end

  let(:now) { Time.utc(2026, 5, 1, 12, 11, 0) }

  it "fires reference_unavailable from the completed window even when a quiet fresh window has begun" do
    windows = [
      alerts_window(Time.utc(2026, 5, 1, 12, 5), writes: 90, unavailable: 10),
      alerts_window(Time.utc(2026, 5, 1, 12, 10), writes: 50)
    ]

    alerts = described_class.evaluate(alerts_window_signals(now:, windows:))

    expect(alerts.map { |alert| [alert.name, alert.company_id, alert.value] })
      .to eq([[:reference_unavailable, 5, Rational(10, 100)]])
  end

  it "ignores a failing window that ended more than one window ago" do
    windows = [alerts_window(Time.utc(2026, 5, 1, 12, 0), writes: 50, unavailable: 50, buckets: { "inf" => 100 })]

    expect(described_class.evaluate(alerts_window_signals(now:, windows:))).to eq([])
  end

  it "reads a p95 in the overflow bucket as over 300 ms" do
    windows = [alerts_window(Time.utc(2026, 5, 1, 12, 10), writes: 10, buckets: { "inf" => 10 })]

    alerts = described_class.evaluate(alerts_window_signals(now:, windows:))

    expect(alerts.map(&:name)).to eq([:entry_write_p95_latency])
    expect(alerts.sole.threshold).to eq(300)
  end

  it "lists each unsourced signal once, including the metrics body shared by two rules" do
    signals = alerts_window_signals(now:, windows: []).with(write_metrics: nil)

    expect(described_class.unsourced(signals)).to eq([:write_metrics])
    expect(described_class.evaluate(signals)).to eq([])
  end
end
